def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # In each row, continue the foreground pattern through its trailing
    # background cells, using 1 to mark the continuation.
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        colored = [c for c, v in enumerate(row) if v != bg]
        if colored:
            for c in range(colored[-1] + 1, w):
                out[r][c] = 1
    return out
